import{STAGES,ACTIVITY_TYPES,initialState,money,today,num,round,saveLead,archiveLead,deleteLead,moveLead,saveCustomer,convertLeadToCustomer,saveActivity,saveQuotation,saveOrder,saveInvoice,convertQuotationToOrder,convertOrderToInvoice,recordPayment,reversePayment,paymentModes,createReturn,creditableInvoiceLines,searchInvoicesByNumber,CREDIT_NOTE_REASON_TYPES,SETTLEMENT_METHODS,salespersonMetrics,salesTeamRoster,saveTeamMember,resolveLegacyTeamEmployeeIds,backfillSalespersonLinkage,customerBalance,crmActivities,filterCrmActivities,dashboardMetrics,reportRows,toCsv,documentTotals,uid}from"./core.js";
import{createWorkspaceStateStorage,createWorkspaceStore}from"/supabase/workspace.js";
import{sharedDepartments}from"/administration-workspace/departments.js";
import{assignedSalespersonName,eligibleSalesEmployees,employeeFullName,employeeOptionLabel,sharedHrEmployees}from"./employees.js";
import{resolveCountryConfig}from"../country/registry.js";
import{renderQuotationDocument}from"./quotation-document.js";
import{renderSalesOrderDocument}from"./sales-order-document.js";
import{renderInvoiceDocument}from"./invoice-document.js";
import{renderCreditNoteDocument}from"./credit-note-document.js";
