// Sales only ever READS Banking here (to suggest an account on the payment form). It never
// writes a Banking transaction directly -- the payment becomes real money only after Finance
// reviews and Confirms & Posts it (src/finance/adapters.js + src/finance/app.js).
const localStorage=await createWorkspaceStateStorage(),bankingRepository=createBankingRepository(localStorage);let inventoryCloud=null,hrCloud=null;
const KEY="infobridgeindia.sales.v1";let state=load(),view="dashboard",query="",filters={status:"",salesperson:"",priority:"",activity:"all",dateFrom:"",dateTo:""},inventoryProducts=[],salesEmployees=[],allHrEmployees=[];
const $=s=>document.querySelector(s),esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c])),date=v=>v?new Intl.DateTimeFormat("en-IN",{dateStyle:"medium"}).format(new Date(v)):"—",dt=v=>v?new Intl.DateTimeFormat("en-IN",{dateStyle:"medium",timeStyle:"short"}).format(new Date(v)):"—";
function load(){try{const x=JSON.parse(localStorage.getItem(KEY));const base=x?.version===1?x:initialState(),fixed=backfillSalespersonLinkage(base);if(fixed.changed)localStorage.setItem(KEY,JSON.stringify(fixed.state));return fixed.state}catch{return initialState()}}function persist(next=state){state=next;localStorage.setItem(KEY,JSON.stringify(state));render()}function toast(s,tone="success"){$("#sales-toast").innerHTML=`<div class="toast ${tone}">${esc(s)}</div>`;setTimeout(()=>$("#sales-toast").innerHTML="",2600)}
async function loadInventory(){try{inventoryCloud=await createWorkspaceStore("inventory");inventoryProducts=(await inventoryCloud.all("products")).filter(x=>x.active!==false);render()}catch{}}
async function loadSalesEmployees(){try{hrCloud=await createWorkspaceStore("hr-payroll");const employees=await sharedHrEmployees({store:hrCloud,storage:globalThis.localStorage,userId:globalThis.InfoBridgeUser?.id,companyId:globalThis.InfoBridgeCompany?.companyId}),departments=sharedDepartments({activeOnly:false,includeIds:employees.map(employee=>employee.departmentId).filter(Boolean)});allHrEmployees=employees;salesEmployees=eligibleSalesEmployees(employees,departments);const resolved=resolveLegacyTeamEmployeeIds(state,employees);if(resolved.changed)persist(resolved.state);else render()}catch(error){console.warn("Sales employees could not be loaded from HR & Payroll.",error);salesEmployees=[];render()}}
const NAV=[["dashboard","Dashboard"],["leads","Leads"],["pipeline","Pipeline"],["customers","Customers"],["followups","Follow-ups"],["products","Products & Services"],["quotations","Quotations"],["orders","Sales Orders"],["invoices","Invoices"],["payments","Payments & Collections"],["returns","Returns & Credit Notes"],["team","Sales Team"],["reports","Reports"]];
const ICONS={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',leads:'<circle cx="9" cy="8" r="4"/><path d="M3 21v-2a6 6 0 0112 0v2M17 8h4M19 6v4"/>',pipeline:'<path d="M4 5h16M7 5v14M17 5v14M4 19h16"/>',customers:'<circle cx="9" cy="8" r="4"/><path d="M3 21v-2a6 6 0 0112 0v2M16 11h5M18.5 8.5v5"/>',followups:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',products:'<path d="M4 7l8-4 8 4-8 4-8-4zM4 7v10l8 4 8-4V7M12 11v10"/>',quotations:'<path d="M6 3h9l3 3v15H6zM9 10h6M9 14h6M9 18h4"/>',orders:'<path d="M5 4h14v16H5zM8 8h8M8 12h8M8 16h5"/>',invoices:'<path d="M6 3h12v18l-3-2-3 2-3-2-3 2zM9 8h6M9 12h6"/>',payments:'<rect x="3" y="6" width="18" height="13" rx="2"/><path d="M3 10h18M7 15h3"/>',returns:'<path d="M9 7H5v-4M5 7a8 8 0 101 10"/>',team:'<circle cx="8" cy="8" r="3"/><circle cx="17" cy="9" r="3"/><path d="M2 20a6 6 0 0112 0M13 20a5 5 0 018-4"/>',reports:'<path d="M4 20V4M4 20h16M8 16v4M12 11v9M16 7v13M20 3v17"/>',search:'<circle cx="11" cy="11" r="7"/><path d="M16 16l5 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',menu:'<path d="M4 7h16M4 12h16M4 17h16"/>'};
function icon(name){return`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]||ICONS.dashboard}</svg>`}
function shell(body){return`<div class="app-shell"><aside class="sidebar" id="side"><a class="sidebar-brand" href="/index.html"><img src="/infobridgeindia-logo.png" alt="InfoBridgeIndia"></a><div class="workspace-label"><strong>Sales & CRM</strong><span>${esc(state.settings.branch)}</span></div><nav>${NAV.map(([v,l])=>`<button class="nav-link ${view===v?"active":""}" data-view="${v}">${icon(v)}<span>${l}</span></button>`).join("")}</nav><div class="local-note">Local-first database<br><span>Last saved automatically</span><a href="/index.html">Exit to website</a></div></aside><main class="main"><header class="topbar"><button class="icon-button mobile-menu" data-menu aria-label="Open menu">${icon("menu")}</button><div class="global-search">${icon("search")}<input data-search value="${esc(query)}" placeholder="Search lead, customer, invoice, activity…"></div></header><div class="content">${body}</div><nav class="mobile-nav">${NAV.slice(0,5).map(([v,l])=>`<button class="${view===v?"active":""}" data-view="${v}">${icon(v)}<span>${l}</span></button>`).join("")}</nav></main></div>`}
const head=(title,desc,actions="")=>`<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div><div class="page-actions">${actions}</div></div>`;
const metric=(l,v)=>`<div class="metric"><span>${l}</span><strong>${v}</strong></div>`,badge=s=>`<span class="badge ${["Paid","Won","Accepted","Delivered","Completed","Active","Valid","Posted"].includes(s)?"success":["Lost","Rejected","Overdue","Cancelled","Inactive","Returned for Correction"].includes(s)?"danger":["Pending","Partially Paid","High"].includes(s)?"warn":""}">${esc(s||"—")}</span>`;
// Surfaces Finance's review decision back onto the source record it was made against -- written
// by src/finance/adapters.js writeSourceReviewStatus() when Finance rejects/returns or Confirms
// & Posts. Sales never writes these fields itself; it only displays them.
function financeStatusCell(x){if(!x.financeStatus)return"—";return`${badge(x.financeStatus)}${x.financeStatus==="Returned for Correction"?`<br><small>${esc(x.financeReason||"")}</small><br><small>${esc(x.financeReviewedBy||"")}${x.financeReviewedAt?` · ${dt(x.financeReviewedAt)}`:""}</small>`:""}`}
function empty(title,msg){return`<div class="empty"><div class="empty-icon">${icon("products")}</div><h3>${title}</h3><p>${msg}</p></div>`}function table(headers,rows){return`<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join("")}</tr></thead><tbody>${rows.join("")}</tbody></table></div>`}
function dashboard(){const m=dashboardMetrics(state),recent=state.leads.filter(x=>!x.archived).slice(0,6),acts=state.activities.filter(x=>x.status==="Pending").sort((a,b)=>a.dateTime.localeCompare(b.dateTime)).slice(0,7),overdue=state.invoices.filter(x=>num(x.balanceDue)>0&&x.dueDate<today()),months=[...Array(6)].map((_,i)=>{const d=new Date();d.setMonth(d.getMonth()-5+i);const k=d.toISOString().slice(0,7);return{label:d.toLocaleString("en",{month:"short"}),value:state.invoices.filter(x=>x.date?.startsWith(k)&&x.status!=="Cancelled").reduce((a,x)=>a+x.grandTotal,0)}}),max=Math.max(1,...months.map(x=>x.value));return`${head("Sales dashboard","Live metrics calculated from saved Sales & CRM records.")}<div class="metrics">${metric("Total Leads",m.totalLeads)}${metric("Today's Follow-ups",m.todayFollowups)}${metric("Overdue Follow-ups",m.overdueFollowups)}${metric("Open Opportunities",m.openOpportunities)}${metric("Quotations Pending",m.quotationsPending)}${metric("Confirmed Orders",m.confirmedOrders)}${metric("Unpaid Invoices",m.unpaidInvoices)}${metric("This Month Sales",money(m.monthSales))}${metric("Month Collected",money(m.monthCollected))}${metric("Total Outstanding",money(m.outstanding))}</div><div class="sales-grid"><section class="panel span8"><div class="panel-head"><h2>Recent leads</h2><button class="text-button" data-view="leads">View all</button></div>${recent.length?leadTable(recent):empty("No leads yet","Add a lead to begin your sales workflow.")}</section><section class="panel span4"><div class="panel-head"><h2>Today's activities</h2></div><div class="padded activity">${acts.length?acts.map(a=>`<div><strong>${esc(a.type)} · ${esc(nameFor(a.relatedId))}</strong><small>${dt(a.dateTime)} · ${esc(a.assignedUser||"Unassigned")}</small></div>`).join(""):"No pending activities."}</div></section><section class="panel span8"><div class="panel-head"><h2>Monthly sales</h2></div><div class="padded chart">${months.map(x=>`<div class="bar" title="${money(x.value)}" style="height:${Math.max(2,x.value/max*100)}%"><span>${x.label}</span></div>`).join("")}</div></section><section class="panel span4"><div class="panel-head"><h2>Overdue payments</h2></div>${overdue.length?table(["Invoice","Balance"],overdue.map(x=>`<tr><td>${esc(x.id)}<small>${esc(customerName(x.customerId))}</small></td><td class="num danger-text">${money(x.balanceDue)}</td></tr>`)):empty("Nothing overdue","Overdue invoices will appear here.")}</section></div>`}
function filtered(rows,keys){const q=query.toLowerCase();return rows.filter(x=>(!q||keys.some(k=>String(x[k]||"").toLowerCase().includes(q)))&&(!filters.status||x.status===filters.status||x.stage===filters.status)&&(!filters.salesperson||x.assignedSalesperson===filters.salesperson)&&(!filters.priority||x.priority===filters.priority))}
function leadTable(rows){return table(["Lead","Contact","Interest","Assigned salesperson","Value","Stage","Follow-up","Actions"],rows.map(x=>`<tr><td><strong>${esc(x.name)}</strong><small>${esc(x.id)} ${x.duplicateWarning?`· <span class="warning">${esc(x.duplicateWarning)}</span>`:""}</small></td><td>${esc(x.mobile)}<small>${esc(x.email)}</small></td><td>${esc(x.interest||"—")}</td><td>${esc(assignedSalespersonName(x,salesEmployees))}</td><td class="num">${money(x.expectedValue)}</td><td>${badge(x.stage)}</td><td>${dt(x.nextFollowup)}</td><td><button class="link" data-edit-lead="${x.id}">Edit</button> <a class="link" href="tel:${esc(x.mobile)}">Call</a> <a class="link" target="_blank" href="https://wa.me/${esc(x.mobile.replace(/\D/g,""))}">WhatsApp</a> <button class="link" data-convert-lead="${x.id}">Convert</button> <button class="link danger-text" data-delete-lead="${x.id}">Delete</button></td></tr>`))}
function leads(){const rows=filtered(state.leads.filter(x=>!x.archived),["id","name","mobile","email","source","interest"]);return`${head("Leads","Capture, qualify, follow up, and convert prospects.",`<button class="btn" data-export="leads">Export CSV</button><button class="btn primary" data-new="lead">Add Lead</button>`)}${filterbar(STAGES)}<section class="panel">${rows.length?leadTable(rows):empty("No matching leads","Add a lead or clear your filters.")}</section>`}
function filterbar(statuses=[]){return`<div class="filters"><input data-filter-search value="${esc(query)}" placeholder="Search"><select data-filter="status"><option value="">All statuses</option>${statuses.map(x=>`<option ${filters.status===x?"selected":""}>${x}</option>`).join("")}</select><select data-filter="priority"><option value="">All priorities</option>${["Low","Medium","High"].map(x=>`<option ${filters.priority===x?"selected":""}>${x}</option>`).join("")}</select><select data-filter="salesperson"><option value="">All salespeople</option>${salespeople().map(x=>`<option ${filters.salesperson===x?"selected":""}>${esc(x)}</option>`).join("")}</select></div>`}
function pipeline(){const leads=filtered(state.leads.filter(x=>!x.archived),["name","interest","source"]);return`${head("Sales pipeline","Drag opportunities between stages; changes save immediately.",`<button class="btn primary" data-new="lead">Add Lead</button>`)}${filterbar(STAGES)}<div class="kanban">${STAGES.map(s=>{const rows=leads.filter(x=>x.stage===s);return`<section class="column" data-stage="${s}"><div class="column-head"><span>${s} (${rows.length})</span><span class="column-total">${money(rows.reduce((a,x)=>a+x.expectedValue,0))}</span></div>${rows.map(x=>`<article class="deal ${x.nextFollowup&&x.nextFollowup.slice(0,10)<today()?"overdue":""}" draggable="true" data-lead="${x.id}"><strong>${esc(x.name)}</strong><p>${esc(x.interest||"No product selected")}</p><p>${money(x.expectedValue)} · ${esc(x.priority||"Medium")}</p><small>${esc(assignedSalespersonName(x,salesEmployees))} · ${dt(x.nextFollowup)}</small></article>`).join("")}</section>`}).join("")}</div>`}
function customers(){const rows=filtered(state.customers,["id","name","mobile","email","gstin","trn"]);return`${head("Customers","Customer master, balances, and connected document history.",`<button class="btn" data-export="customers">Export CSV</button><button class="btn primary" data-new="customer">Add Customer</button>`)}<section class="panel">${rows.length?table(["Customer","Contact","GSTIN","Terms","Sales","Outstanding","Status",""],rows.map(c=>{const sales=state.invoices.filter(i=>i.customerId===c.id).reduce((a,i)=>a+i.grandTotal,0);return`<tr><td><strong>${esc(c.name)}</strong><small>${esc(c.id)}</small></td><td>${esc(c.mobile)}<small>${esc(c.email)}</small></td><td>${esc(c.trn||c.gstin||"Unregistered")}</td><td>${num(c.paymentTerms)} days</td><td class="num">${money(sales)}</td><td class="num">${money(customerBalance(state,c.id))}</td><td>${badge(c.active!==false?"Active":"Inactive")}</td><td><button class="link" data-customer="${c.id}">View</button><button class="link" data-edit-customer="${c.id}">Edit</button></td></tr>`})):empty("No customers yet","Convert a lead or add a customer.")}</section>`}
function followups(){const rows=filtered(state.activities,["type","notes","outcome","assignedUser"]),day=today();return`${head("Follow-ups & activities","Calls, messages, meetings, tasks, notes, reminders, and outcomes.",`<button class="btn primary" data-new="activity">Add Activity</button>`)}<div class="filterbar">${[["all","All"],["today","Today"],["upcoming","Upcoming"],["overdue","Overdue"]].map(([x,l])=>`<button class="filter" data-activity-filter="${x}">${l}</button>`).join("")}</div><section class="panel">${rows.length?table(["When","Related to","Type","Assigned","Outcome / next action","Status",""],rows.map(a=>`<tr><td>${dt(a.dateTime)}</td><td>${esc(nameFor(a.relatedId))}</td><td>${badge(a.type)}</td><td>${esc(a.assignedUser||assignedSalespersonName(state.leads.find(lead=>lead.id===a.relatedId),salesEmployees)||"—")}</td><td>${esc(a.outcome||a.nextAction||a.notes||"—")}</td><td>${badge(a.status)}</td><td>${a.status==="Pending"?`<button class="link" data-complete-activity="${a.id}">Complete</button>`:""}<button class="link" data-edit-activity="${a.id}">Edit</button></td></tr>`)):empty("No activities yet","Schedule the next action from a lead or customer.")}</section>`}
function products(){const rows=[...inventoryProducts.map(p=>({...p,type:"Product",hsnSac:p.hsn||p.hsnSac,gstRate:p.gstRate||0,currentStock:p.quantity??"See Inventory"})),...state.services];return`${head("Products & services","Products are read from the existing Inventory catalog; services are maintained here.",`<a class="btn" href="/inventory/index.html">Open Inventory</a><button class="btn primary" data-new="service">Add Service</button>`)}<section class="panel">${rows.length?table(["Type","Name","SKU","HSN / SAC","Unit","Selling price","GST","Stock","Status"],rows.map(x=>`<tr><td>${x.type||"Product"}</td><td><strong>${esc(x.name)}</strong></td><td>${esc(x.sku||"—")}</td><td>${esc(x.hsnSac||"—")}</td><td>${esc(x.unit||"unit")}</td><td class="num">${money(x.sellingPrice)}</td><td>${num(x.gstRate)}%</td><td>${esc(x.currentStock??"—")}</td><td>${badge(x.active!==false?"Active":"Inactive")}</td></tr>`)):empty("No products or services","Add inventory products or create a service.")}</section>`}
function docs(type){const cfg={quotations:["Quotations",state.quotations,"quotation",["Draft","Sent","Accepted","Rejected"]],orders:["Sales Orders",state.orders,"order",["Draft","Confirmed","Processing","Dispatched","Delivered","Cancelled"]],invoices:["Invoices",state.invoices,"invoice",["Unpaid","Partially Paid","Paid","Overdue","Cancelled"]]},[title,rows,kind,statuses]=cfg[type],visible=filtered(rows,["id","status","notes"]),description=type==="quotations"?"Connected quotations with country-aware tax calculations and source traceability.":`Connected ${title.toLowerCase()} with country-aware tax calculations and source traceability.`;return`${head(title,description,`<button class="btn" data-export="${type}">Export CSV</button><button class="btn primary" data-new="${kind}">Create ${kind}</button>`)}${filterbar(statuses)}<section class="panel">${visible.length?table(["Number","Date","Customer / prospect","Reference","Taxable","Tax","Total","Status","Actions"],visible.map(x=>`<tr><td><strong>${esc(x.id)}</strong></td><td>${date(x.date)}</td><td>${esc(x.partyName||customerName(x.customerId))}</td><td>${esc(x.leadId||x.quotationId||x.orderId||"—")}</td><td class="num">${money(x.taxable)}</td><td class="num">${money(x.tax??(x.cgst+x.sgst+x.igst+x.vat))}</td><td class="num"><strong>${money(x.grandTotal)}</strong>${type==="invoices"?`<small>Balance ${money(x.balanceDue)}</small>`:""}</td><td>${badge(x.status)}</td><td><button class="link" data-preview="${type}:${x.id}">Preview</button>${type==="quotations"&&!x.orderId?` <button class="link" data-q-order="${x.id}">To order</button>`:""}${type==="orders"&&!x.invoiceId?` <button class="link" data-o-invoice="${x.id}">To invoice</button>`:""}</td></tr>`)):empty(`No ${title.toLowerCase()} yet`,`Create one to continue the connected sales flow.`)}</section>`}
function payments(){const outstanding=state.invoices.filter(x=>num(x.balanceDue)>0&&x.status!=="Cancelled");return`${head("Payments & collections","Record partial or full payments and keep invoice balances current.",`<button class="btn primary" data-new="payment">Record Payment</button>`)}<section class="panel"><div class="panel-head"><h2>Outstanding invoices</h2></div>${outstanding.length?table(["Invoice No.","Customer","Invoice Date","Due Date","Total","Paid","Balance","Status","Action"],outstanding.map(x=>`<tr><td><strong>${esc(x.id)}</strong></td><td>${esc(customerName(x.customerId))}</td><td>${date(x.date)}</td><td>${date(x.dueDate)}</td><td class="num">${money(x.grandTotal)}</td><td class="num">${money(x.amountPaid)}</td><td class="num">${money(x.balanceDue)}</td><td>${badge(x.status)}</td><td><button class="link" data-record-payment="${x.id}">Record Payment</button></td></tr>`)):empty("All collected","No invoice has an outstanding balance.")}</section><section class="panel"><div class="panel-head"><h2>Payment register</h2></div>${state.payments.length?table(["Receipt No.","Payment Date","Invoice No.","Customer","Payment Mode","Reference","Amount","Finance Status","Action"],state.payments.map(x=>`<tr><td>${esc(x.id)}</td><td>${date(x.date)}</td><td>${esc(x.invoiceId)}</td><td>${esc(customerName(x.customerId))}</td><td>${esc(x.mode)}</td><td>${esc(x.reference||"—")}</td><td class="num">${money(x.amount)}</td><td>${financeStatusCell(x)}</td><td>${x.status!=="Reversed"?`<button class="link danger-text" data-reverse="${x.id}">Reverse</button>`:'<span class="badge danger">Reversed</span>'}</td></tr>`)):empty("No collections recorded","Record a payment against an invoice.")}</section>`}
function returns(){return`${head("Returns & credit notes","Create credit notes for returns, cancellations, billing corrections, discounts, and invoice adjustments.",`<button class="btn primary" data-new="return">Create Credit Note</button>`)}<section class="panel">${state.returns.length?table(["Credit Note No.","Date","Customer","Original Invoice","Reason","Taxable Credit","Tax","Total Credit","Settlement","Status","Actions"],state.returns.map(x=>`<tr><td><strong>${esc(x.id)}</strong></td><td>${date(x.date)}</td><td>${esc(customerName(x.customerId))}</td><td>${esc(x.invoiceId)}</td><td>${esc(x.reasonType||"—")}</td><td class="num">${money(x.taxable)}</td><td class="num">${money(x.tax??(num(x.cgst)+num(x.sgst)+num(x.igst)+num(x.vat)))}</td><td class="num"><strong>${money(x.grandTotal)}</strong></td><td>${esc(x.settlementMethod||"—")}</td><td>${badge(x.status)}</td><td><button class="link" data-preview="returns:${x.id}">Preview</button></td></tr>`)):empty("No credit notes yet","Create a credit note against an existing invoice.")}</section>`}
function teamRoster(){return salesTeamRoster(state,allHrEmployees)}
function team(){const roster=teamRoster();return`${head("Sales team","Assignments, targets, conversion, sales, and collections from saved records.",`<button class="btn primary" data-new="team">Add Team Member</button>`)}<section class="panel">${roster.length?table(["Salesperson","Target","Leads","Won / Lost","Sales","Collections","Conversion"],roster.map(person=>{const m=salespersonMetrics(state,{employeeId:person.employeeId,name:person.name});return`<tr><td><strong>${esc(person.name)}</strong>${person.designation?`<small>${esc(person.designation)}</small>`:""}</td><td class="num">${money(person.target)}</td><td>${m.leads}</td><td>${m.won} / ${m.lost}</td><td class="num">${money(m.sales)}</td><td class="num">${money(m.collections)}</td><td>${m.conversion}%</td></tr>`})):empty("No salespeople","Add a team member or assign a lead.")}</section>`}
const REPORTS=[...REPORT_TYPES,"Lead Conversion","Pipeline","Lead Source","Lost Lead Reasons","Product-wise Sales","Quotation Status","Order Status"];
function reportContext(){return{from:filters.dateFrom||"",to:filters.dateTo||"",company:globalThis.InfoBridgeCompany,employees:allHrEmployees}}
function reports(){const selected=filters.report||REPORTS[0],professional=REPORT_TYPES.includes(selected);let body;if(professional){const report=buildReport(state,selected,reportContext());body=`${report.summary.length?`<div class="metrics">${report.summary.map(x=>metric(x.label,x.value)).join("")}</div>`:""}<section class="panel"><div class="panel-head"><h2>${selected}</h2><strong>${report.rows.length} records</strong></div>${report.rows.length?table(report.columns,report.rows.map(row=>`<tr>${report.columns.map(c=>`<td>${esc(row[c])}</td>`).join("")}</tr>`)):empty("No report data","Records will appear as you complete the connected sales workflow.")}</section>`}else{const rows=reportRows(state,selected);body=`<section class="panel"><div class="panel-head"><h2>${selected}</h2><strong>${rows.length} records</strong></div>${rows.length?genericTable(rows):empty("No report data","Records will appear as you complete the connected sales workflow.")}</section>`}return`${head("Sales reports","Reports contain only records saved in this workspace.",`<button class="btn" data-export-report>Export CSV</button><button class="btn primary" data-preview-report>Preview Report</button>`)}<div class="filters"><select data-report>${REPORTS.map(x=>`<option ${x===selected?"selected":""}>${x}</option>`).join("")}</select><input type="date" data-date-from value="${esc(filters.dateFrom||"")}"><input type="date" data-date-to value="${esc(filters.dateTo||"")}"></div>${body}`}
function genericTable(rows){const keys=[...new Set(rows.flatMap(Object.keys))].filter(k=>!["items","history","billingAddress","shippingAddress"].includes(k)&&typeof rows[0]?.[k]!=="object").slice(0,8);return table(keys.map(k=>k.replace(/([A-Z])/g," $1")),rows.slice(0,100).map(r=>`<tr>${keys.map(k=>`<td>${typeof r[k]==="number"?money(r[k]):esc(r[k])}</td>`).join("")}</tr>`))}
function customerName(id){return state.customers.find(x=>x.id===id)?.name||"Unknown customer"}function nameFor(id){return state.leads.find(x=>x.id===id)?.name||customerName(id)}function teamMemberName(member){if(member.employeeId){const employee=allHrEmployees.find(e=>String(e.id)===String(member.employeeId));if(employee)return employeeFullName(employee)}return member.name||""}function salespeople(){return[...new Set([...state.team.map(teamMemberName),...state.leads.map(x=>x.assignedSalesperson)].filter(Boolean))]}
function salesEmployeeSelect(record={}){const selected=record.assignedSalespersonId||salesEmployees.find(employee=>employeeFullName(employee)===record.assignedSalesperson)?.id||"",historical=selected&&!salesEmployees.some(employee=>String(employee.id)===String(selected))?`<option value="${esc(selected)}" selected>${esc(record.assignedSalesperson||"Previously assigned employee")}</option>`:"",options=salesEmployees.map(employee=>`<option value="${esc(employee.id)}" ${String(employee.id)===String(selected)?"selected":""}>${esc(employeeOptionLabel(employee))}</option>`).join("");return`<label class="salesperson-field">Assigned salesperson<select name="assignedSalespersonId"><option value="">Select salesperson</option>${historical}${options||'<option value="" disabled>No sales employees available</option>'}</select>${salesEmployees.length?"":'<small class="salesperson-helper">No sales employees available. Assign an employee to the Sales & CRM department in HR & Payroll.</small>'}</label>`}
