function syncedFollowups(){const q=query.toLowerCase(),all=crmActivities(state).filter(a=>{const lead=a.lead||state.leads.find(x=>x.id===a.relatedId);return!q||[a.type,a.notes,a.outcome,a.nextAction,a.assignedUser,lead?.name,lead?.contactPerson,lead?.mobile,lead?.email,lead?.interest,lead?.stage].some(value=>String(value||"").toLowerCase().includes(q))}),rows=filterCrmActivities(all,filters.activity).sort((a,b)=>a.dateTime.localeCompare(b.dateTime));return`${head("Follow-ups & activities","Calls, messages, meetings, tasks, notes, reminders, and outcomes.",`<button class="btn primary" data-new="activity">Add Activity</button>`)}<div class="filterbar">${[["all","All"],["today","Today"],["upcoming","Upcoming"],["overdue","Overdue"]].map(([value,label])=>`<button class="filter ${filters.activity===value?"active":""}" data-activity-filter="${value}">${label}</button>`).join("")}</div><section class="panel">${rows.length?table(["When","Customer / contact","Type","Assigned","Interest / next action","Stage","Contact","Status",""],rows.map(a=>{const lead=a.lead||state.leads.find(x=>x.id===a.relatedId);return`<tr><td>${dt(a.dateTime)}</td><td><strong>${esc(nameFor(a.relatedId))}</strong>${lead?.contactPerson?`<small>${esc(lead.contactPerson)}</small>`:""}</td><td>${badge(a.type)}</td><td>${esc(a.assignedUser||assignedSalespersonName(lead,salesEmployees)||"—")}</td><td>${esc(lead?.interest||a.outcome||a.nextAction||a.notes||"—")}</td><td>${lead?badge(lead.stage):"—"}</td><td>${lead?`${esc(lead.mobile||"—")}<small>${esc(lead.email||"")}</small>`:"—"}</td><td>${badge(a.status)}</td><td>${a.isLeadFollowup?`<button class="link" data-edit-lead="${lead.id}">Edit lead</button>`:`${a.status==="Pending"?`<button class="link" data-complete-activity="${a.id}">Complete</button>`:""}<button class="link" data-edit-activity="${a.id}">Edit</button>`}</td></tr>`})):empty("No matching activities","Add a next follow-up to a lead or create an activity.")}</section>`}
